function klimat_checkout_escape($value) { return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function klimat_checkout_money($value, $currency) { return number_format((float) $value, 2, ',', ' ') . ' ' . $currency; }
function klimat_checkout_view(array $data, array $values, array $errors, $review, $csrf, $selfPath)
{
